-- People on a sheet, listed in the order they were added (by id). A grade is one of A, B or C.
CREATE TABLE person (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    name     VARCHAR(200) NOT NULL,
    grade    VARCHAR(1)   NOT NULL CHECK (grade IN ('A', 'B', 'C'))
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- A person may have aliases. An alias shares the names' uniqueness on the sheet: compared without
-- regard to case and ignoring surrounding spaces, it equals no name and no other alias there. Aliases
-- are stored trimmed; alias_key is the trimmed, lower-cased alias the uniqueness among aliases is kept on.
CREATE TABLE person_alias (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    person_id BIGINT NOT NULL REFERENCES person (id),
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    alias     VARCHAR(200) NOT NULL,
    alias_key VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX person_alias_sheet_key ON person_alias (sheet_id, alias_key);
-- A transfer merged into a person who already has one of the arriving names keeps both, so one person
-- may hold aliases sharing a key. Different people still never share a name or alias key on the sheet:
-- that is kept by the app; the index stays for finding people by alias.
DROP INDEX person_alias_sheet_key;
CREATE INDEX person_alias_sheet_key ON person_alias (sheet_id, alias_key);
-- A person's place in the list, lowest first. A person added carries none until they are moved, and
-- takes their id's place, which is after everyone added before them; a move swaps two people's places.
ALTER TABLE person ADD COLUMN position BIGINT;
UPDATE person SET position = id;
